#include <iostream>
#include <vector>

int main() {
    std::vector<int> v{3, 1, 2};
    for (std::size_t i = 0; i + 1 < v.size(); ++i) {
        std::size_t best = i;
        for (std::size_t j = i + 1; j < v.size(); ++j) if (v[j] < v[best]) best = j;
        int tmp = v[i];
        v[i] = v[best];
        v[best] = tmp;
    }
    for (int x : v) std::cout << x << " ";
    std::cout << "\n";
    return 0;
}

