class Calculator {
public:
    explicit Calculator(std::function<int(int, int)> op) : op(std::move(op)) {}
    int run(int a, int b) const { return op(a, b); }
private:
    std::function<int(int, int)> op;
};

int main() {
    Calculator add([](int a, int b) { return a + b; });
    std::cout << add.run(2, 3) << "\n";
    return 0;
}

